CREATE TABLE `body_builder` (`Body_Builder_ID` DECIMAL(18,2), `People_ID` DECIMAL(18,2), `Snatch` DECIMAL(18,2), `Clean_Jerk` DECIMAL(18,2), `Total` DECIMAL(18,2));
CREATE TABLE `people` (`People_ID` DECIMAL(18,2), `Name` VARCHAR(100), `Height` DECIMAL(18,2), `Weight` DECIMAL(18,2), `Birth_Date` VARCHAR(100), `Birth_Place` VARCHAR(100));
